// Writes src/types.gen.ts: the API types the SDK uses, fully expanded from @couryo/contract
// (which is internal and built on zod). The published package then has no dependency on the
// contract or on zod. Run with `pnpm --filter @couryo/node gen:types` after the contract changes;
// test/types.test.ts fails while the generated file is out of date.
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import ts from "typescript";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const contractDts = fileURLToPath(import.meta.resolve("@couryo/contract")).replace(/index\.js$/, "index.d.ts");

/** Every contract type the SDK imports or re-exports. */
export const NAMES = [
  "Audience", "AudienceCount", "BatchSendResponse", "Campaign", "CampaignPreflight", "CampaignStats", "CampaignStatus",
  "Contact", "CreateCampaignRequest", "TrackEventRequest", "TrackEventResponse", "UpdateCampaignRequest",
  "CheckEmailResponse", "CreateTemplateRequest", "Domain", "DomainHealth", "Email", "EmailEvent", "EmailEventType",
  "EmailStatus", "List", "Period", "PreviewTemplateResponse", "SendEmailRequest", "SendEmailResponse", "Suppression",
  "SuppressionReason", "SuppressionStream", "Template", "TemplateVersion", "UpdateTemplateRequest", "Webhook", "WebhookPayload",
  "ContactImport", "CreateContactImportRequest", "Topic", "InboxTest", "CreateInboxTestRequest",
  "WebhookEventType", "ContactUnsubscribedPayload", "ContactTopicChangedPayload", "SuppressionWebhookPayload", "AnyWebhookPayload",
  "DailyLimitSettings", "DailyLimitResponse",
];

const program = ts.createProgram([contractDts], { strict: true, target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.NodeNext, moduleResolution: ts.ModuleResolutionKind.NodeNext });
const checker = program.getTypeChecker();
const file = program.getSourceFile(contractDts);
const moduleSymbol = checker.getSymbolAtLocation(file);
const exports = new Map(checker.getExportsOfModule(moduleSymbol).map((s) => [s.getName(), s]));

const flags = ts.TypeFormatFlags.NoTruncation | ts.TypeFormatFlags.InTypeAlias | ts.TypeFormatFlags.UseSingleQuotesForStringLiteralType;
const out = [
  "// Generated by scripts/gen-types.mjs from the Couryo API contract. Do not edit by hand.",
  "",
];
for (const name of NAMES) {
  let sym = exports.get(name);
  if (!sym) throw new Error(`contract does not export ${name}`);
  if (sym.flags & ts.SymbolFlags.Alias) sym = checker.getAliasedSymbol(sym);
  const decl = sym.declarations?.find((d) => ts.isTypeAliasDeclaration(d) || ts.isInterfaceDeclaration(d));
  if (!decl) throw new Error(`${name} has no type declaration`);
  if (decl.typeParameters?.length) {
    // Generic helpers (List<T>) are plain TypeScript in the contract: copy the declaration as written.
    out.push(decl.getText().replace(/^export\s+(declare\s+)?/, "export "), "");
    continue;
  }
  const type = checker.getTypeAtLocation(decl);
  const text = checker.typeToString(type, undefined, flags);
  out.push(`export type ${name} = ${text};`, "");
}
const target = join(root, "src", "types.gen.ts");
writeFileSync(target, out.join("\n"));
console.log(`wrote ${target} (${NAMES.length} types)`);
